service.method:

DELETE 
  FROM #DB_OWNER#SLANG 
 WHERE SCREEN_ID  = ${SCREEN_ID}
   AND CODE       = ${CODE}
   AND HOUSE_CODE = ${session.HOUSE_CODE}


SELECT COUNT(*) CNT
  FROM #DB_OWNER#SLANG 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND LANGUAGE   = ${LANGUAGE}
   AND SCREEN_ID  = ${SCREEN_ID}
   AND CODE       = ${CODE}


	UPDATE #DB_OWNER#SLANG
       SET CONTENTS    = ${CONTENTS}
		  ,CHANGE_DATE = ${current.DATE}
		  ,CHANGE_TIME = ${current.TIME}
	 WHERE HOUSE_CODE  = ${session.HOUSE_CODE}
	   AND LANGUAGE    = ${LANGUAGE}
	   AND SCREEN_ID   = ${SCREEN_ID}
	   AND CODE        = ${CODE}


INSERT
    INTO #DB_OWNER#SLANG_HISTORY
      (
          HISTORY_KEY
        , ACTION_MODE
        , HOUSE_CODE
        , SCREEN_ID
        , LANGUAGE
        , CODE
        , CONTENTS
        , ADD_USER_ID
        , ADD_DATE
        , ADD_TIME
        , GRID_WIDTH
        , FORM_WIDTH
      )
VALUES(
          ${HISTORY_KEY}
        , ${ACTION_MODE}
        , ${session.HOUSE_CODE}
        , ${SCREEN_ID}
        , ${LANGUAGE}
        , ${CODE}
        , ${CONTENTS}
        , ${session.ID}
        , ${current.DATE}
        , ${current.TIME}
        , ${GRID_WIDTH}
        , ${FORM_WIDTH}
     )
